plate = [60, 40, 4];
hole = 3.2;
difference() {
    translate([0, 0, plate[2] / 2]) cube(plate, center = true);
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx * 25, sy * 15, -1]) cylinder(d = hole, h = plate[2] + 2, $fn = 96);
    translate([0, 0, -1]) cylinder(r = 10, h = plate[2] + 2, $fn = 128);
}

